30	/** A map from host names to datanode descriptors. */
31	@InterfaceAudience.Private
32	@InterfaceStability.Evolving
33	class Host2NodesMap {
34	  private HashMap<String, String> mapHost = new HashMap<String, String>();
35	  private final HashMap<String, DatanodeDescriptor[]> map
36	    = new HashMap<String, DatanodeDescriptor[]>();
37	  private final ReadWriteLock hostmapLock = new ReentrantReadWriteLock();
38	
39	  /** Check if node is already in the map. */
40	  boolean contains(DatanodeDescriptor node) {
41	    if (node==null) {
42	      return false;
43	    }
44	      
45	    String ipAddr = node.getIpAddr();
46	    hostmapLock.readLock().lock();
47	    try {
48	      DatanodeDescriptor[] nodes = map.get(ipAddr);
49	      if (nodes != null) {
50	        for(DatanodeDescriptor containedNode:nodes) {
51	          if (node==containedNode) {
52	            return true;
53	          }
54	        }
55	      }
56	    } finally {
57	      hostmapLock.readLock().unlock();
58	    }
59	    return false;
60	  }
61	    
62	  /** add node to the map 
63	   * return true if the node is added; false otherwise.
64	   */
65	  boolean add(DatanodeDescriptor node) {
66	    hostmapLock.writeLock().lock();
67	    try {
68	      if (node==null || contains(node)) {
69	        return false;
70	      }
71	      
72	      String ipAddr = node.getIpAddr();
73	      String hostname = node.getHostName();
74	      
75	      mapHost.put(hostname, ipAddr);
76	      
77	      DatanodeDescriptor[] nodes = map.get(ipAddr);
78	      DatanodeDescriptor[] newNodes;
79	      if (nodes==null) {
80	        newNodes = new DatanodeDescriptor[1];
81	        newNodes[0]=node;
82	      } else { // rare case: more than one datanode on the host
83	        newNodes = new DatanodeDescriptor[nodes.length+1];
84	        System.arraycopy(nodes, 0, newNodes, 0, nodes.length);
85	        newNodes[nodes.length] = node;
86	      }
87	      map.put(ipAddr, newNodes);
88	      return true;
89	    } finally {
90	      hostmapLock.writeLock().unlock();
91	    }
92	  }
93	    
94	  /** remove node from the map 
95	   * return true if the node is removed; false otherwise.
96	   */
97	  boolean remove(DatanodeDescriptor node) {
98	    if (node==null) {
99	      return false;
100	    }
101	      
102	    String ipAddr = node.getIpAddr();
103	    String hostname = node.getHostName();
104	    hostmapLock.writeLock().lock();
105	    try {
106	
107	      DatanodeDescriptor[] nodes = map.get(ipAddr);
108	      if (nodes==null) {
109	        return false;
110	      }
111	      if (nodes.length==1) {
112	        if (nodes[0]==node) {
113	          map.remove(ipAddr);
114	          //remove hostname key since last datanode is removed
115	          mapHost.remove(hostname);
116	          return true;
117	        } else {
118	          return false;
119	        }
120	      }
121	      //rare case
122	      int i=0;
123	      for(; i<nodes.length; i++) {
124	        if (nodes[i]==node) {
125	          break;
126	        }
127	      }
128	      if (i==nodes.length) {
129	        return false;
130	      } else {
131	        DatanodeDescriptor[] newNodes;
132	        newNodes = new DatanodeDescriptor[nodes.length-1];
133	        System.arraycopy(nodes, 0, newNodes, 0, i);
134	        System.arraycopy(nodes, i+1, newNodes, i, nodes.length-i-1);
135	        map.put(ipAddr, newNodes);
136	        return true;
137	      }
138	    } finally {
139	      hostmapLock.writeLock().unlock();
140	    }
141	  }
