143	  /**
144	   * Get a data node by its IP address.
145	   * @return DatanodeDescriptor if found, null otherwise 
146	   */
147	  DatanodeDescriptor getDatanodeByHost(String ipAddr) {
148	    if (ipAddr == null) {
149	      return null;
150	    }
151	      
152	    hostmapLock.readLock().lock();
153	    try {
154	      DatanodeDescriptor[] nodes = map.get(ipAddr);
155	      // no entry
156	      if (nodes== null) {
157	        return null;
158	      }
159	      // one node
160	      if (nodes.length == 1) {
161	        return nodes[0];
162	      }
163	      // more than one node
164	      return nodes[ThreadLocalRandom.current().nextInt(nodes.length)];
165	    } finally {
166	      hostmapLock.readLock().unlock();
167	    }
168	  }
